   if(nodes.Any(n=>n!["control"]?.ToString()!="next"))throw new InvalidOperationException("Coordinate the existing serial output graph; branch regions remain protected");
   var deleted=nodes.Where(n=>n!["kind"]?.ToString()=="export"&&removed.Contains(n["output"]!.ToString())).Select(n=>n!["id"]!.ToString()).ToHashSet(StringComparer.Ordinal);var edges=graph["edges"]!.AsArray();
   string Resolve(string target){var seen=new HashSet<string>(StringComparer.Ordinal);while(deleted.Contains(target)){if(!seen.Add(target))throw new InvalidOperationException("Output removal encountered a cycle");string id=target;target=edges.SingleOrDefault(e=>e!["from"]!.ToString()==id&&e["port"]!.ToString()=="next")?["to"]?.ToString()??"";}return target.StartsWith("exit:",StringComparison.Ordinal)&&removed.Contains(target[5..])?"":target;}
   var kept=new JsonArray();foreach(var edge in edges){if(deleted.Contains(edge!["from"]!.ToString()))continue;string to=Resolve(edge["to"]!.ToString());if(to.Length==0)continue;var row=edge.DeepClone();row["to"]=to;kept.Add(row);}graph["entry"]=Resolve(graph["entry"]!.ToString());graph["edges"]=kept;
   foreach(var node in nodes.Where(n=>deleted.Contains(n!["id"]!.ToString())).ToArray())nodes.Remove(node);
