   if(plan["outputCreates"] is JsonArray creates){if(creates.Count>64)throw new ArgumentException("Output creation budget");foreach(var item in creates){var row=item!.AsObject();if(row.Any(p=>p.Key is not ("node" or "output" or "valueJson")))throw new ArgumentException("Explicit output assignment fields required");string id=row["node"]!.GetValue<string>(),name=row["output"]!.GetValue<string>();if(id.Length>128||!System.Text.RegularExpressions.Regex.IsMatch(id,@"\A[A-Za-z_][A-Za-z_0-9.-]*\z")||nodes.Any(n=>n!["id"]!.ToString()==id)||!declared.TryGetValue(name,out string? type))throw new ArgumentException("New unique assignment and declared output required");nodes.Add(new JsonObject{["id"]=id,["kind"]="export",["control"]="next",["intent"]="Assign "+name,["output"]=name,["signature"]=new JsonObject{["args"]=new JsonArray(new JsonObject{["name"]="value",["type"]=type}),["return"]="void"},["arguments"]=new JsonObject{["value"]=row["valueJson"] is null?null:JsonNode.Parse(row["valueJson"]!.GetValue<string>())}});}}
